package transcript

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"time"
)

// BindReplayValues identifies recorded string values generated by the client per run.
// It returns recorded-to-actual pairs without mutating its inputs or performing I/O.
type BindReplayValues func(expected, actual map[string]any) (map[string]string, error)

// ServeReplay plays steps against a client. bind may be nil.
func ServeReplay(stdin io.Reader, stdout io.Writer, steps []Step, bind BindReplayValues) error {
	reader := bufio.NewReader(stdin)
	bindings := make(map[string]string)
	enc := json.NewEncoder(stdout)

	for index, step := range steps {
		switch step.Kind {
		case "recv":
			if err := serveRecvStep(reader, step, bind, bindings); err != nil {
				return fmt.Errorf("step %d recv: %w", index, err)
			}
		case "send":
			if err := serveSendStep(enc, step, bindings); err != nil {
				return fmt.Errorf("step %d send: %w", index, err)
			}
		default:
			return fmt.Errorf("step %d: unknown kind %q", index, step.Kind)
		}
	}

	line, err := readReplayLine(reader)
	if err == nil {
		return fmt.Errorf("unexpected extra input: %s", line)
	}
	if !errors.Is(err, io.EOF) {
		return fmt.Errorf("read replay stdin: %w", err)
	}
	return nil
}

func readReplayLine(reader *bufio.Reader) ([]byte, error) {
	line, err := reader.ReadBytes('\n')
	if errors.Is(err, io.EOF) && len(line) > 0 {
		return line, nil
	}
	if err != nil {
		return line, fmt.Errorf("read replay line: %w", err)
	}
	return line, nil
}

func serveRecvStep(reader *bufio.Reader, step Step, bind BindReplayValues, bindings map[string]string) error {
	line, err := readReplayLine(reader)
	if err != nil {
		return err
	}
	var actual any
	if err := json.Unmarshal(line, &actual); err != nil {
		return fmt.Errorf("parse input json: %w", err)
	}
	if bind != nil {
		expectedObject, expectedOK := step.Match.(map[string]any)
		actualObject, actualOK := actual.(map[string]any)
		if !expectedOK || !actualOK {
			return fmt.Errorf("binding requires JSON objects")
		}
		pairs, err := bind(expectedObject, actualObject)
		if err != nil {
			return err
		}
		if err := updateReplayBindings(bindings, pairs); err != nil {
			return err
		}
	}
	return matchReplayValue(substituteReplayValues(step.Match, bindings), actual)
}

func updateReplayBindings(bindings, pairs map[string]string) error {
	for recorded, actual := range pairs {
		if recorded == "" || actual == "" {
			return fmt.Errorf("empty replay binding")
		}
		if previous, ok := bindings[recorded]; ok && previous != actual {
			return fmt.Errorf("recorded value %q already bound", recorded)
		}
		for other, value := range bindings {
			if value == actual && other != recorded {
				return fmt.Errorf("actual value %q already bound", actual)
			}
		}
		bindings[recorded] = actual
	}
	return nil
}

func substituteReplayValues(value any, bindings map[string]string) any {
	switch value := value.(type) {
	case string:
		if replacement, ok := bindings[value]; ok {
			return replacement
		}
	case map[string]any:
		result := make(map[string]any, len(value))
		for key, item := range value {
			result[key] = substituteReplayValues(item, bindings)
		}
		return result
	case []any:
		result := make([]any, len(value))
		for index, item := range value {
			result[index] = substituteReplayValues(item, bindings)
		}
		return result
	}
	return value
}

func serveSendStep(enc *json.Encoder, step Step, bindings map[string]string) error {
	if step.DelayMS > 0 {
		time.Sleep(time.Duration(step.DelayMS) * time.Millisecond)
	}
	if err := enc.Encode(substituteReplayValues(step.Message, bindings)); err != nil {
		return fmt.Errorf("encode replay output: %w", err)
	}
	return nil
}
